 +`<div class="grid-4">${statCard('TRACKED BANKROLL',money(b.bankroll),'Available minus pending: '+money(b.available),'◈')}${statCard('REALIZED PROFIT',money(b.profit,true),num(b.units,3)+'u total','↗',b.profit>=0?'green':'red')}${statCard('RECORD',b.wins+'–'+b.losses,b.cashouts+' cash-outs · '+b.pending+' pending','▣')}${statCard('UNIT SIZE',money(b.unit),'Set in Settings','◎')}</div>`
 +`<section class="card" style="margin-top:20px"><div class="card-head" style="padding:24px 24px 0"><h2>All Bets</h2><span class="tag">${state.bets.length} TRACKED</span></div>${state.bets.length?betRows(state.bets,true):empt('No bets','Add your first bet with the button above')}</section>`
